entries[79134] = { ["name"] = "Vergiftende Wunden", ["text"] = "Jedes Mal, wenn Eure Fähigkeiten 'Blutung' oder 'Erdrosseln' einem von Euch vergifteten Ziel Schaden zufügen, besteht eine Chance von 75%, dass es zusätzlich 685 Naturschaden erleidet und Ihr 10 Energie zurückgewinnt. Eure Fähigkeit 'Erdrosseln' wird diesen effekt nicht auslösen, wenn der Gegner bereits von Eurem Effekt 'Blutung' betroffen ist.\n\nWenn das Ziel stirbt, während es vom Effekt Eurer Fähigkeit 'Blutung' betroffen ist, gewinnt Ihr Energie proportional zur verbleibenden Effektdauer von 'Blutung' zurück.\n(Procchance: 75%)" }
